import{_ as p,a0 as r,w as d,s as o,ao as l,I as e,a1 as t,A as n,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"為集中管理的用户提供 FIDO2 認證 | LCTT x X-CMD","titleTemplate":false,"description":"為集中管理的用户提供 FIDO2 認證 | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為集中管理的用户提供 FIDO2 認證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為集中管理的用户提供 FIDO2 認證 | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20231113 FIDO2 for centrally managed users","title":"為集中管理的用户提供 FIDO2 認證","tag":"202311","desc":""},"relativePath":"202311/20231113 FIDO2 for centrally managed users.md","filePath":"[post].md"}'),u={name:"202311/20231113 FIDO2 for centrally managed users.md"};function g(f,s,h,k,b,m){const i=r("Link");return d(),o("div",null,[s[41]||(s[41]=l('<h1 id="為集中管理的用户提供-fido2-認證" tabindex="-1">為集中管理的用户提供 FIDO2 認證 <a class="header-anchor" href="#為集中管理的用户提供-fido2-認證" aria-label="Permalink to “為集中管理的用户提供 FIDO2 認證”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202311/23/095049o1kdwqugdgw5d1mk.png" alt=""></p><p>Fedora 39 通過 SSSD 和 FreeIPA 為集中管理的用户開啓了 FIDO2 認證功能。此篇文章將指導你如何進行配置和啓用該功能。</p><h3 id="fido2" tabindex="-1">FIDO2 <a class="header-anchor" href="#fido2" aria-label="Permalink to “FIDO2”">​</a></h3>',4)),e("p",null,[t(i,{href:"https://fidoalliance.org/fido2/"},{default:n(()=>[...s[0]||(s[0]=[a("FIDO2",-1)])]),_:1}),s[2]||(s[2]=a(" 是以 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Public-key_cryptography"},{default:n(()=>[...s[1]||(s[1]=[a("公鑰加密",-1)])]),_:1}),s[3]||(s[3]=a(" 為基礎的開放式認證標準，比起密碼和一次性密碼（OTP），它的安全性更高且易用性更強。它通常以類似小型 USB 和基於 NFC 的硬件安全令牌的方式提供。有幾種符合 FIDO 認可的密鑰品牌，例如：YubiKey、NitroKey、SoloKey v2 等等。",-1))]),s[42]||(s[42]=e("p",null,"此協議的優勢包括：",-1)),e("ul",null,[s[7]||(s[7]=e("li",null,"通過使用公鑰加密來消除密碼，從而實現無密碼認證。",-1)),e("li",null,[s[5]||(s[5]=a("採用 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Multi-factor_authentication"},{default:n(()=>[...s[4]||(s[4]=[a("多因素認證",-1)])]),_:1}),s[6]||(s[6]=a("（MFA）以實現強力認證。",-1))]),s[8]||(s[8]=e("li",null,"減少了應用程序之間密碼或公鑰的重複使用，降低數據泄露的風險。",-1)),s[9]||(s[9]=e("li",null,"私鑰位於安全令牌中並且永不離開，這大大減少了被網絡釣魚的威脅。",-1))]),s[43]||(s[43]=e("h4",{id:"前面的文章",tabindex:"-1"},[a("前面的文章 "),e("a",{class:"header-anchor",href:"#前面的文章","aria-label":"Permalink to “前面的文章”"},"​")],-1)),e("p",null,[s[12]||(s[12]=a("在 Fedora 雜誌中，有多篇文章闡述瞭如 FIDO2 的應用場景：《",-1)),t(i,{href:"https://fedoramagazine.org/use-fido-u2f-security-keys-with-fedora-linux/"},{default:n(()=>[...s[10]||(s[10]=[a("如何使用 FIDO2 驗證本地用户",-1)])]),_:1}),s[13]||(s[13]=a("》 和 《",-1)),t(i,{href:"https://fedoramagazine.org/use-systemd-cryptenroll-with-fido-u2f-or-tpm2-to-decrypt-your-disk/"},{default:n(()=>[...s[11]||(s[11]=[a("如何解鎖硬盤",-1)])]),_:1}),s[14]||(s[14]=a("》。而此篇文章介紹瞭如何使用 FIDO2 驗證遠程用户。請注意，上述所説的設備，主要是指那些來自 Yubico 採用了其他協議的設備，而此篇指南的目的並非討論這些協議。",-1))]),s[44]||(s[44]=e("h3",{id:"集中管理的用户",tabindex:"-1"},[a("集中管理的用户 "),e("a",{class:"header-anchor",href:"#集中管理的用户","aria-label":"Permalink to “集中管理的用户”"},"​")],-1)),e("p",null,[t(i,{href:"https://sssd.io/"},{default:n(()=>[...s[15]||(s[15]=[a("SSSD",-1)])]),_:1}),s[21]||(s[21]=a(" 和 ",-1)),t(i,{href:"https://freeipa.readthedocs.io/en/latest/"},{default:n(()=>[...s[16]||(s[16]=[a("FreeIPA",-1)])]),_:1}),s[22]||(s[22]=a(" 最近新增了一個名為 ",-1)),e("ruby",null,[t(i,{href:"https://fedoraproject.org/wiki/Changes/Passkey_authentication_centrally_managed_users"},{default:n(()=>[...s[17]||(s[17]=[a("通行密鑰",-1)])]),_:1}),s[18]||(s[18]=e("rt",null,"passkey",-1))]),s[23]||(s[23]=a(" 的特性，以便對集中管理的用户執行 FIDO2 認證。此功能目前只在 ",-1)),t(i,{href:"https://sssd.io/release-notes/sssd-2.9.0.html"},{default:n(()=>[...s[19]||(s[19]=[a("SSSD 2.9.0",-1)])]),_:1}),s[24]||(s[24]=a(" 和 ",-1)),t(i,{href:"https://www.freeipa.org/release-notes/4-11-0.html"},{default:n(()=>[...s[20]||(s[20]=[a("FreeIPA 4.11.0",-1)])]),_:1}),s[25]||(s[25]=a(" 等版本中支持。",-1))]),s[45]||(s[45]=l(`<p>Fedora 39 已經包含了這些版本，因此，它是第一個為集中管理的用户啓用 FIDO2 認證的發行版。此外，用户在認證成功後，也會一併獲取一個 Kerberos 票據，實現對其他服務的身份證明。</p><p>請注意，從這裏開始，我將交替使用 FIDO2 和通行密鑰這兩個術語。</p><h3 id="fido2-認證" tabindex="-1">FIDO2 認證 <a class="header-anchor" href="#fido2-認證" aria-label="Permalink to “FIDO2 認證”">​</a></h3><h4 id="fido2-配置" tabindex="-1">FIDO2 配置 <a class="header-anchor" href="#fido2-配置" aria-label="Permalink to “FIDO2 配置”">​</a></h4><p>作為額外的安全措施，應在設備中啓用 MFA 以防你丟失了密鑰，惡意行為者無法使用它進行認證。</p><p>列出連接的通行密鑰設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fido2-token -L</span></span></code></pre></div><p>為你的通行密鑰設備設置 PIN（將大寫字母替換為所需的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fido2-token -C /dev/hidrawX</span></span></code></pre></div><p>如果你有一個兼容的設備，你還可以啓用其他認證因素，例如指紋。</p><h4 id="集中用户配置" tabindex="-1">集中用户配置 <a class="header-anchor" href="#集中用户配置" aria-label="Permalink to “集中用户配置”">​</a></h4><p>首先，我們來創建一個用户，並將通行密鑰（<code>passkey</code>）設置為其認證方式（請根據需要將大寫字母替換為相應的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipa user-add USERNAME --first NAME --last SURNAME --user-auth-type=passkey</span></span></code></pre></div><p>或者，如果你已有一個用户，並只需要將 <code>passkey</code> 設置為其認證方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipa user-mod USERNAME --user-auth-type=passkey</span></span></code></pre></div><h4 id="集中管理用户的-fido2-註冊" tabindex="-1">集中管理用户的 FIDO2 註冊 <a class="header-anchor" href="#集中管理用户的-fido2-註冊" aria-label="Permalink to “集中管理用户的 FIDO2 註冊”">​</a></h4><p>接下來，我們為該用户註冊這個通行密鑰。這個步驟會提示你輸入 PIN 碼，隨後觸摸設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipa user-add-passkey USERNAME --register</span></span>
<span class="line"><span>Enter PIN:</span></span>
<span class="line"><span>Please touch the device.</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>Added passkey mappings to user &quot;USERNAME&quot;</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>    User login: USERNAME</span></span>
<span class="line"><span>    Passkey mapping: passkey:XR/MXigmgiBz1z7/RlWoWZkXKIEf1x9Ux5uPNxtzzSTdTiF407u2nRYMPkK8pWjwUR8Aa2urCcC9cnpLbkKgFg==,MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEZqgERsFFv4Yev1dyo2Ap4PvLirg3P3Uhig5mNA4qf061C9q5rg0nMDz9AOYxZmBrwvQEXHCasMNO9VAIVnBIVg==</span></span></code></pre></div><p>此刻，用户的認證已準備就緒。</p><p>注意，如果你想在生產環境中使用此用户，我建議你至少註冊兩個不同的設備。這樣，即使你丟失了其中一個設備，你也可以用另一個進行認證。</p><h4 id="集中管理的用户的-fido2-認證" tabindex="-1">集中管理的用户的 FIDO2 認證 <a class="header-anchor" href="#集中管理的用户的-fido2-認證" aria-label="Permalink to “集中管理的用户的 FIDO2 認證”">​</a></h4><p>在初次嘗試中，只有在物理連接令牌的系統中才能進行認證。這意味着你可以使用 <code>su</code> 或圖形界面，但不能遠程使用 ssh。</p><p>我們來試試使用 <code>su</code>，記得將大寫字母替換為所需的。當要求你輸入 PIN，然後觸摸設備時，當設備燈閃爍時觸摸它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ su - USERNAME@DOMAIN</span></span>
<span class="line"><span>Insert your passkey device, then press ENTER.</span></span>
<span class="line"><span>Enter PIN:</span></span></code></pre></div><p>如果一切進行順利，Kerberos 票據也應已被授予，然後你就可以向其他服務進行遠程認證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ klist</span></span>
<span class="line"><span>Ticket cache: KCM:879400005:34862</span></span>
<span class="line"><span>Default principal: USERNAME@DOMAIN</span></span>
<span class="line"><span>Valid starting Expires        Service principal</span></span>
<span class="line"><span>10/20/23 09:46:04  10/21/23 09:32:37  krbtgt/DOMAIN@DOMAIN</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>此認證機制的目標是提升安全性。通過使用一種眾所周知、開放式的標準實現無密碼和多因素認證，從而降低數據泄露和網絡釣魚威脅的風險。用户只需要一個硬件令牌及另外一個如 PIN 或者指紋的認證方式，從而消除對密碼的需求，同時提供了方便的多因素認證方法。更進一步，每個應用或服務都使用一個唯一的密鑰，這樣任何一個應用或服務的數據泄露都不會影響其他的。最後，用户並不需要知道他們的憑據的具體細節，只需瞭解他們使用了一個實體令牌，這極大地降低了社交工程攻擊的可能性。</p><p><em>（題圖：MJ/838d5392-79b4-4c22-ab0f-c2ada4bf2833）</em></p><hr>`,30)),e("p",null,[s[27]||(s[27]=a("via: ",-1)),t(i,{href:"https://fedoramagazine.org/fido2-for-centrally-managed-users/"},{default:n(()=>[...s[26]||(s[26]=[a("https://fedoramagazine.org/fido2-for-centrally-managed-users/",-1)])]),_:1})]),e("p",null,[s[32]||(s[32]=a("作者：",-1)),t(i,{href:"https://fedoramagazine.org/author/ipedrosa/"},{default:n(()=>[...s[28]||(s[28]=[a("Iker Pedrosa",-1)])]),_:1}),s[33]||(s[33]=a(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[29]||(s[29]=[a("lujun9972",-1)])]),_:1}),s[34]||(s[34]=a(" 譯者：",-1)),t(i,{href:"https://linux.cn/lctt/ChatGPT"},{default:n(()=>[...s[30]||(s[30]=[a("ChatGPT",-1)])]),_:1}),s[35]||(s[35]=a(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[31]||(s[31]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[38]||(s[38]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[36]||(s[36]=[a("LCTT",-1)])]),_:1}),s[39]||(s[39]=a(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[37]||(s[37]=[a("Linux中國",-1)])]),_:1}),s[40]||(s[40]=a(" 榮譽推出",-1))])])}const F=p(u,[["render",g]]);export{D as __pageData,F as default};
